SELECT m.id,e.date,e.name event,e.type,e.surface,m.round,m.status,m.winner,m.loser,m.winner_rank,m.loser_rank,m.score,pw.name winner_name,pl.name loser_name FROM matches m JOIN events e ON e.id=m.event LEFT JOIN players pw ON pw.id=m.winner LEFT JOIN players pl ON pl.id=m.loser WHERE (m.winner IN ('SY67','SX50') OR m.loser IN ('SY67','SX50')) AND e.date BETWEEN '2025-01-01' AND '2026-10-19' AND m.status IN ('Completed','Aborted') ORDER BY e.date,m.id